const items = $input.all();
const outcomes = items.map(i => i.json).filter(j => j && j.id);
const total = outcomes.length;
const minSample = 5;
const nowIso = new Date().toISOString().slice(0, 10);

if (total < minSample) {
  const card = `🧠 <b>Balanço Semanal de Aprendizado 360 (WF-104)</b>\n` +
    `📅 <i>Semana: ${nowIso}</i>\n\n` +
    `• <b>Amostra insuficiente na semana:</b> ${total} registros observados (Mínimo: ${minSample}).\n` +
    `• Nenhuma diretriz foi inferida automaticamente para preservar a integridade das decisões.\n` +
    `• O motor continuará acumulando desfechos para o próximo ciclo.`;
  return [{ json: { chat_id: 5281600644, text: card, insufficient: true, total } }];
}

let accepted = 0;
let edited = 0;
let rejected = 0;
const patterns = {};

for (const o of outcomes) {
  if (o.outcome_type === 'ACEITO_INTEGRAL') accepted++;
  else if (o.outcome_type === 'EDITADO_POR_RAFAEL') {
    edited++;
    const key = `${o.domain || 'GERAL'}:${o.delta_analysis?.edit_type || 'MODIFICADO'}`;
    patterns[key] = (patterns[key] || 0) + 1;
  }
  else if (o.outcome_type === 'RECUSADO_COM_MOTIVO') {
    rejected++;
    const key = `${o.domain || 'GERAL'}:REJEITADO`;
    patterns[key] = (patterns[key] || 0) + 1;
  }
}

const useful = accepted + edited;
const durPct = ((useful / total) * 100).toFixed(1);
const targetMet = durPct >= 85.0;
const statusIcon = targetMet ? '🟢 <b>META BATIDA</b>' : '🟡 <b>ABAIXO DA META</b>';

const candidates = [];
for (const [key, count] of Object.entries(patterns)) {
  if (count >= 2) {
    const [dom, type] = key.split(':');
    const candidateId = Math.random().toString(36).substring(2, 10);
    let rule = `Ajustar propostas em ${dom} conforme preferências de Rafael.`;
    if (type === 'MADE_MORE_CONCISE') rule = `Em ${dom}, gerar propostas mais concisas e objetivas.`;
    else if (type === 'EXPANDED_DETAILS') rule = `Em ${dom}, detalhar os impactos operacionais antes do envio.`;
    else if (type === 'REJEITADO') rule = `Em ${dom}, reavaliar ofertas e argumentos previamente recusados.`;
    candidates.push({ id: candidateId, rule, count, domain: dom });
  }
}

let card = `🧠 <b>Balanço Semanal de Aprendizado 360 (WF-104)</b>\n` +
  `📅 <i>Semana: ${nowIso}</i>\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n` +
  `📊 <b>Métricas de Assertividade da IA:</b>\n` +
  `• <b>Total de Propostas:</b> ${total}\n` +
  `• <b>Aceitas / Úteis:</b> ${useful} (${durPct}% de utilidade)\n` +
  `• <b>Ajustadas por Você:</b> ${edited}\n` +
  `• <b>Recusadas:</b> ${rejected}\n` +
  `• <b>Status da Meta (DUR ≥ 85%):</b> ${statusIcon}\n\n`;

if (candidates.length === 0) {
  card += `💡 <b>Lições Candidatas:</b> Nenhuma divergência recorrente detectada nesta semana.\n`;
} else {
  card += `💡 <b>Lições Candidatas a Promoção:</b>\n`;
  for (let i = 0; i < candidates.length; i++) {
    const c = candidates[i];
    card += `${i + 1}. <b>${c.rule}</b> (Detectado ${c.count}x) — <code>/aprovardiretriz ${c.id}</code>\n`;
  }
  card += `\n👉 <i>Para aprovar todas as diretrizes acima:</i> <code>/aprovar_todas</code>\n`;
}

card += `━━━━━━━━━━━━━━━━━━━━━━━━━━\n_Nenhuma diretriz opera sem sua aprovação explícita (Governança N2.3)._`;
return [{ json: { chat_id: 5281600644, text: card, insufficient: false, durPct, total, candidates } }];
